    color: #555;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #f0f0f0;
}

.thread-root-message {
    padding: 12px 16px;
    background: #f9f9f9;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-divider {
    margin: 0;
    border: none;
    border-top: 1px solid #e8e8e8;
}

